package org.plainphone.device.approval

import org.junit.Assert.*
import org.junit.Test
import org.plainphone.core.PackageName
import org.plainphone.device.DevicePolicyPort
import org.plainphone.policy.AppApprovalOutcome
import org.plainphone.policy.PolicyPlan

/**
 * The PLA-229 reviewer's probes (review document on PLA-229), verbatim, kept as regressions. The two
 * final-readback probes (finding 1) run on [RoundTwoHarness], generated by the review's script; they
 * need the device side of the `:policy` containment port (PLA-234, PLA-237).
 */
class VerifierRoundTwoProbeTest {
    @Test fun failedFinalReadbackMustContainApproval() = RoundTwoHarness().use { h ->
        h.beforeReadBack = { h.port.restrictionSet.clear() }
        assertEquals(AppApprovalOutcome.NOT_READY, h.approve())
        println("approval: ${h.state()} pending=${h.approvals.pending?.phase}")
        assertFalse("NOT_READY must not leave new access: ${h.state()}", h.visibleAndPermitted())
    }
    @Test fun failedFinalReadbackMustContainEdit() = RoundTwoHarness().use { h ->
        assertEquals(AppApprovalOutcome.APPROVED, h.approve())
        h.beforeReadBack = { h.port.restrictionSet.clear() }
        assertEquals(AppApprovalOutcome.NOT_READY, h.edit())
        println("edit: ${h.state()} pending=${h.approvals.pending?.phase}")
        assertFalse("NOT_READY must not leave new access: ${h.state()}", h.visibleAndPermitted())
    }
    @Test fun nullUidOfListedPackageMustRefuseBeforeUnhide() = ApprovalHarness().use { h ->
        val port = object : DevicePolicyPort by h.port {
            override fun uid(name: PackageName): Int? = if (name == h.dialer) null else h.port.uid(name)
        }
        val e = DeviceApprovalEffects(h.dispatcher, port, h.grants, h.home, h.neverHide) { null }
        h.dispatcher.run {
            val opened = e.openPermissionWindow(h.identity)
            println("null allowed UID: opened=$opened ${h.state()}")
            try { assertFalse("cannot prove exclusion with a null allowed UID", opened) }
            finally { e.closePermissionWindow(h.identity) }
        }
    }
    @Test fun failedPublishMustVerifyHomeRemoval() = ApprovalHarness().use { h ->
        lateinit var plan: PolicyPlan
        h.beforeApply = { plan = it }
        assertEquals(AppApprovalOutcome.APPROVED, h.approve())
        h.port.setHidden(h.target, true)
        h.port.setLockTaskPackages(h.port.lockTask - h.target)
        val listed = mutableSetOf<PackageName>()
        var removalReads = 0
        val home = object : HomeAppList {
            override fun publish(names: Set<PackageName>) { listed.addAll(names); error("partly published") }
            override fun remove(name: PackageName) { /* failed write that requires readback */ }
            override fun lists(name: PackageName): Boolean { removalReads++; return name in listed }
        }
        val e = DeviceApprovalEffects(h.dispatcher, h.port, h.grants, home, h.neverHide) { null }
        assertFalse(h.dispatcher.run { e.applyPolicy(plan) })
        println("failed publish: hidden=${h.port.hidden(h.target.value)} permitted=${h.target in h.port.lockTask} home=${h.target in listed} removalReads=$removalReads")
        assertTrue("Home containment must read back removal", removalReads > 0)
    }
}
